    s=s.replace("\n","\\n")
    return s[:n]+("..." if len(s)>n else "")
for i,l in enumerate(lines):
    try:
        o=json.loads(l)
    except:
        print(i,"UNPARSEABLE", short(l)); continue
    t=o.get("type")
