        print(i,"SYSTEM", o.get("subtype"))
    elif t=="assistant":
        msg=o.get("message",{})
        for c in msg.get("content",[]):
            ct=c.get("type")
            if ct=="thinking":
                print(i,"THINK:", short(c.get("thinking","")))
            elif ct=="text":
                print(i,"TEXT:", short(c.get("text","")))
            elif ct=="tool_use":
                print(i,"TOOL_USE", c.get("name"), short(json.dumps(c.get("input",{})),300))
